  const [svc] = await db
    .select()
    .from(s.services)
    .where(and(eq(s.services.id, serviceId), eq(s.services.businessId, session.businessId)));
  if (!st || !svc) return;
  const [link] = await db
    .select()
    .from(s.staffServices)
    .where(and(eq(s.staffServices.staffId, staffId), eq(s.staffServices.serviceId, serviceId)));
