    await db
      .delete(s.staffServices)
      .where(and(eq(s.staffServices.staffId, staffId), eq(s.staffServices.serviceId, serviceId)));
  } else {
    await db.insert(s.staffServices).values({ staffId, serviceId });
  }
  revalidatePath("/admin/staff");
